        /// <Summary>
        /// return view for CodeFirstDatabase.PrepaidCollect
        /// </Summary>
        private System.Collections.Generic.KeyValuePair<string, string> GetView0()
        {
            return new System.Collections.Generic.KeyValuePair<string, string>("CodeFirstDatabase.PrepaidCollect", @"
    SELECT VALUE -- Constructing PrepaidCollect
        [CodeFirstDatabaseSchema.PrepaidCollect](T1.PrepaidCollect_Id, T1.PrepaidCollect_Name, T1.PrepaidCollect_DisplayInLOV, T1.PrepaidCollect_SearchFields)
    FROM (
        SELECT 
            T.Id AS PrepaidCollect_Id, 
            T.Name AS PrepaidCollect_Name, 
            T.DisplayInLOV AS PrepaidCollect_DisplayInLOV, 
            T.SearchFields AS PrepaidCollect_SearchFields, 
            True AS _from0
        FROM WebFreightContext.PrepaidCollects AS T
    ) AS T1");
        }
        
